 780→      }}
 781→      titleMetadata={
 782→        isAdmin ? <Badge tone="info">Admin</Badge> : undefined
 783→      }
 784→    >
 785→      <Box paddingBlockEnd="1600">
 786→        <Layout>
 787→
 788→          {/* ---- Stats Bar ---- */}
 789→          <Layout.Section>
 790→            <InlineGrid columns={{ xs: 2, sm: 2, md: 5 }} gap="400">
 791→              <Box
 792→                padding="400"
 793→                background="bg-surface"
 794→                borderWidth="025"
 795→                borderColor="border"
 796→                borderRadius="200"
 797→              >
 798→                <BlockStack gap="100">
 799→                  <Text as="p" tone="subdued" variant="bodySm">
 800→                    Total Requests
