1190→              maxLength={150}
1191→              showCharacterCount
1192→              helpText="Keep it short and descriptive."
1193→            />
1194→            <TextField
1195→              label="Description"
1196→              value={newDescription}
1197→              onChange={setNewDescription}
1198→              placeholder="Describe the feature and why it would be valuable..."
1199→              autoComplete="off"
1200→              multiline={4}
1201→              maxLength={MAX_DESCRIPTION_LENGTH}
1202→              showCharacterCount
1203→              helpText="The more context you provide, the better we can understand your needs."
