1227→      >
1228→        <Modal.Section>
1229→          <BlockStack gap="400">
1230→            {editModalError && (
1231→              <Banner tone="critical" onDismiss={() => setEditModalError(null)}>
1232→                {editModalError}
1233→              </Banner>
