                    const isExpanded = expandedIds.has(feature.id);
                    const needsTruncation = feature.description.length > 160;
                    const displayDescription = isExpanded
                      ? feature.description
                      : truncateText(feature.description, 160);

                    return (
                      <Box
                        key={feature.id}
                        padding="400"
                        background="bg-surface"
                        borderWidth="025"
                        borderColor="border"
                        borderRadius="300"
                      >
                        <InlineStack
                          gap="400"
                          align="start"
                          blockAlign="start"
                          wrap={false}
                        >
                          {/* Vote button */}
                          <Box minWidth="64px">
                            <Box
                              padding="200"
                              background={isVoted ? "bg-surface-success" : "bg-surface-secondary"}
                              borderRadius="200"
                              borderWidth="025"
                              borderColor={isVoted ? "border-success" : "border"}
                            >
                              <BlockStack gap="100" inlineAlign="center">
                                <Button
                                  variant={isVoted ? "primary" : "tertiary"}
                                  size="slim"
                                  icon={ChevronUpIcon}
                                  onClick={() => handleVote(feature.id)}
                                  loading={
                                    pendingVoteId === feature.id &&
                                    voteFetcher.state !== "idle"
                                  }
                                  accessibilityLabel={
                                    isVoted
                                      ? "Remove vote"
                                      : "Vote for this feature"
                                  }
                                />
                                <Text
                                  as="p"
                                  variant="headingSm"
                                  fontWeight="bold"
                                  alignment="center"
                                  tone={isVoted ? "success" : undefined}
                                >
                                  {feature.votesCount}
                                </Text>
                                <Text
                                  as="p"
                                  variant="bodySm"
                                  alignment="center"
                                  tone={isVoted ? "success" : "subdued"}
                                >
                                  {isVoted ? "voted" : "vote"}
                                </Text>
                              </BlockStack>
                            </Box>
                          </Box>

                          {/* Content */}
                          <Box width="100%">
                            <BlockStack gap="200">
                              <InlineStack
                                align="space-between"
                                blockAlign="start"
                                wrap
                              >
                                <Text
                                  as="p"
                                  variant="headingSm"
                                  fontWeight="semibold"
                                >
                                  {feature.title}
                                </Text>
                                {isAdmin ? (
                                  <Box minWidth="140px">
                                    <Select
                                      label="Status"
                                      labelHidden
                                      options={STATUS_OPTIONS}
                                      value={feature.status}
                                      onChange={(val) =>
