content.content:
  1→/**
  2→ * Centralized Resend email service.
  3→ *
  4→ * All send functions return `true` on success, `false` on failure — they never
  5→ * throw. This lets callers fire-and-forget without wrapping in try/catch.
  6→ */
  7→import { Resend } from "resend";
  8→
  9→// ---------------------------------------------------------------------------
 10→// Types
 11→// ---------------------------------------------------------------------------
 12→
 13→export interface EmailOptions {
 14→  /** Display name in the From field (e.g. "Cool Store"). Defaults to shopDisplayName. */
 15→  senderName?: string | null;
 16→  /** Cached Shopify store display name (from ShopSettings.shopName). Falls back to myshopify slug. */
 17→  shopDisplayName?: string | null;
 18→  /** Reply-to email for customer-facing emails. If empty, no reply-to header is added. */
 19→  replyTo?: string | null;
 20→}
 21→
 22→// ---------------------------------------------------------------------------
 23→// Client singleton
 24→// ---------------------------------------------------------------------------
 25→
 26→let client: Resend | null = null;
 27→
 28→function getClient(): Resend | null {
 29→  if (client) return client;
 30→  const apiKey = process.env.RESEND_API_KEY;
 31→  if (!apiKey) {
 32→    console.warn("[email] RESEND_API_KEY not set — emails will be skipped");
 33→    return null;
 34→  }
 35→  client = new Resend(apiKey);
 36→  return client;
 37→}
 38→
 39→function getRawFromEmail(): string {
 40→  return process.env.RESEND_FROM_EMAIL || "noreply@example.com";
 41→}
 42→
 43→function shopFallbackName(shop: string, options?: EmailOptions): string {
 44→  return options?.shopDisplayName?.trim() || shop.replace(".myshopify.com", "");
 45→}
 46→
 47→/**
 48→ * Build the full From address with display name.
 49→ *
 50→ * - Custom sender name set:  "Cool Store via Pinzo <noreply@boldteq.app>"
 51→ * - No custom name:          "cool-store via Pinzo <noreply@boldteq.app>"
 52→ */
 53→function buildFrom(shop: string, options?: EmailOptions): string {
 54→  const displayName = options?.senderName?.trim() || shopFallbackName(shop, options);
 55→  return `${displayName} via Pinzo <${getRawFromEmail()}>`;
 56→}
 57→
 58→/**
 59→ * Build optional reply_to field. Returns undefined when not configured
 60→ * so it can be spread into the Resend payload without adding an empty header.
 61→ */
 62→function buildReplyTo(options?: EmailOptions): { reply_to: string } | Record<string, never> {
 63→  const replyTo = options?.replyTo?.trim();
 64→  if (replyTo) return { reply_to: replyTo };
 65→  return {};
 66→}
 67→
 68→/**
 69→ * Wrap email body content in a branded layout with Pinzo logo header and store name.
 70→ */
 71→function emailLayout(storeName: string, body: string): string {
 72→  return `
 73→    <div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;background:#ffffff">
 74→      <div style="padding:24px 24px 16px;border-bottom:1px solid #e5e7eb;text-align:center">
 75→        <table cellpadding="0" cellspacing="0" border="0" style="margin:0 auto">
 76→          <tr>
 77→            <td style="vertical-align:middle;padding-right:10px">
 78→              <div style="width:36px;height:36px;background:#e6f4ef;border-radius:50%;text-align:center;line-height:36px;font-size:18px">&#x1F4CD;</div>
 79→            </td>
 80→            <td style="vertical-align:middle">
 81→              <span style="font-size:20px;font-weight:700;color:#1a1a1a;letter-spacing:-0.3px">Pinzo</span>
 82→            </td>
 83→          </tr>
 84→        </table>
 85→        <p style="margin:8px 0 0;font-size:13px;color:#6b7280">${storeName}</p>
 86→      </div>
 87→      <div style="padding:24px">
 88→        ${body}
 89→      </div>
 90→      <div style="padding:16px 24px;border-top:1px solid #e5e7eb;text-align:center">
 91→        <p style="margin:0;font-size:12px;color:#9ca3af">Powered by <span style="color:#008060;font-weight:600">Pinzo</span></p>
 92→      </div>
 93→    </div>
 94→  `;
 95→}
 96→
 97→// ---------------------------------------------------------------------------
 98→// 1. Waitlist Confirmation  (App → Customer)
 99→// ---------------------------------------------------------------------------
100→
101→export async function sendWaitlistConfirmation(
102→  to: string,
103→  zipCode: string,
104→  shop: string,
105→  options?: EmailOptions,
106→): Promise<boolean> {
107→  const resend = getClient();
108→  if (!resend) return false;
109→
110→  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
111→
112→  try {
113→    await resend.emails.send({
114→      from: buildFrom(shop, options),
115→      to,
116→      subject: `You're on the waitlist — ${name}`,
117→      html: emailLayout(name, `
118→          <h2 style="margin:0 0 16px;color:#1a1a1a">You're on the waitlist!</h2>
119→          <p style="color:#374151;line-height:1.6">Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
120→          <p style="color:#6b7280;font-size:13px;margin-top:24px">— ${name}</p>
121→      `),
122→      text: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
123→      ...buildReplyTo(options),
124→    });
125→    return true;
126→  } catch (error) {
127→    console.error("[email] Failed to send waitlist confirmation:", error);
128→    return false;
129→  }
130→}
131→
132→// ---------------------------------------------------------------------------
133→// 2. Merchant Alert  (App → Merchant)
134→// ---------------------------------------------------------------------------
135→
136→export async function sendMerchantWaitlistAlert(
137→  to: string,
138→  customerEmail: string,
139→  zipCode: string,
140→  shop: string,
141→  options?: EmailOptions,
142→): Promise<boolean> {
143→  const resend = getClient();
144→  if (!resend) return false;
145→
146→  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
147→
148→  try {
149→    await resend.emails.send({
150→      from: buildFrom(shop, options),
151→      to,
152→      subject: `New waitlist signup: ${zipCode}`,
153→      html: emailLayout(name, `
154→          <h2 style="margin:0 0 16px;color:#1a1a1a">New waitlist signup</h2>
155→          <p style="color:#374151;line-height:1.6">A customer just joined the waitlist for ZIP code <strong>${zipCode}</strong>.</p>
156→          <table style="margin:16px 0;border-collapse:collapse">
157→            <tr><td style="padding:4px 12px 4px 0;color:#6b7280">Email</td><td style="color:#1a1a1a">${customerEmail}</td></tr>
158→            <tr><td style="padding:4px 12px 4px 0;color:#6b7280">ZIP Code</td><td style="color:#1a1a1a">${zipCode}</td></tr>
159→          </table>
160→          <p style="color:#6b7280;font-size:13px">You can manage the waitlist from your <strong>${name}</strong> admin dashboard.</p>
161→      `),
162→      text: `New waitlist signup\n\nA customer (${customerEmail}) just joined the waitlist for ZIP code ${zipCode}.\n\nManage the waitlist from your ${name} admin dashboard.`,
163→      ...buildReplyTo(options),
164→    });
165→    return true;
166→  } catch (error) {
167→    console.error("[email] Failed to send merchant waitlist alert:", error);
168→    return false;
169→  }
170→}
171→
172→// ---------------------------------------------------------------------------
173→// 3. ZIP Available Notification  (App → Customer)
174→// ---------------------------------------------------------------------------
175→
176→export async function sendZipAvailableNotification(
177→  to: string,
178→  zipCode: string,
179→  shop: string,
180→  shopUrl: string,
181→  options?: EmailOptions,
182→): Promise<boolean> {
183→  const resend = getClient();
184→  if (!resend) return false;
185→
186→  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
187→
188→  try {
189→    await resend.emails.send({
190→      from: buildFrom(shop, options),
191→      to,
192→      subject: `Great news! We now deliver to ${zipCode}`,
193→      html: emailLayout(name, `
194→          <h2 style="margin:0 0 16px;color:#1a1a1a">Great news!</h2>
195→          <p style="color:#374151;line-height:1.6">We're excited to let you know that delivery is now available to ZIP code <strong>${zipCode}</strong>.</p>
196→          <p style="margin-top:16px"><a href="${shopUrl}" style="display:inline-block;padding:12px 24px;background:#008060;color:#ffffff;text-decoration:none;border-radius:6px;font-weight:600;font-size:15px">Shop Now</a></p>
197→          <p style="color:#6b7280;font-size:13px;margin-top:24px">— ${name}</p>
198→      `),
199→      text: `Great news!\n\nDelivery is now available to ZIP code ${zipCode}. Visit ${shopUrl} to place your order.\n\n— ${name}`,
200→      ...buildReplyTo(options),
201→    });
202→    return true;
203→  } catch (error) {
204→    console.error("[email] Failed to send ZIP available notification:", error);
205→    return false;
206→  }
207→}
208→
209→// ---------------------------------------------------------------------------
210→// 4. Test Email  (Settings page)
211→// ---------------------------------------------------------------------------
212→
213→export async function sendTestEmail(
214→  to: string,
215→  options?: EmailOptions,
216→  shop?: string,
217→): Promise<boolean> {
218→  const resend = getClient();
219→  if (!resend) return false;
220→
221→  const name = options?.senderName?.trim() || (shop ? shopFallbackName(shop, options) : "Your Store");
222→
223→  try {
224→    await resend.emails.send({
225→      from: buildFrom(shop || "test-store.myshopify.com", options),
226→      to,
227→      subject: "Pinzo — Test Email",
228→      html: emailLayout(name, `
229→          <h2 style="margin:0 0 16px;color:#1a1a1a">Test email received!</h2>
230→          <p style="color:#374151;line-height:1.6">Your email integration is working correctly.</p>
231→          <p style="margin-top:16px;color:#374151"><strong>From:</strong> ${name} via Pinzo &lt;${getRawFromEmail()}&gt;</p>
232→          ${options?.replyTo ? `<p style="color:#374151"><strong>Reply-To:</strong> ${options.replyTo}</p>` : '<p style="color:#374151"><strong>Reply-To:</strong> <em>Not set</em></p>'}
