  </script>
{% else %}

<div
  id="zcc-widget-{{ block.id }}"
  data-zcc-widget="true"
  data-shop="{{ shop.permanent_domain }}"
  data-api="{{ app.url }}"
  data-proxy="/apps/zipcheck"
  data-block="{{ block.id }}"
  {{ block.shopify_attributes }}
></div>

<script>
(function () {
  // Wait for app embed to set window.__zccAppEnabled.
  // App embed (target: body) may load after this section block, so we poll briefly.
  var maxWait = 3000; // ms
  var interval = 50;  // ms
  var elapsed = 0;

  function tryInit() {
    if (window.__zccAppEnabled) {
      init();
    } else if (elapsed < maxWait) {
      elapsed += interval;
      setTimeout(tryInit, interval);
    }
    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
  }

  // Start checking — if already set, runs immediately
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', tryInit);
  } else {
    tryInit();
  }

  function init() {
  var ROOT_ID = "zcc-widget-{{ block.id }}";
  var container = document.getElementById(ROOT_ID);
  if (!container) return;

  var SHOP = container.dataset.shop;
  // app.url resolves to the App Proxy URL (e.g. https://store.myshopify.com/apps/zipcheck).
  // If for any reason it is empty (e.g. dev environment or Shopify Liquid context issue),
  // fall back to the relative proxy path so the request still routes correctly through
  // Shopify's App Proxy rather than hitting the store's own domain as a missing route.
  var _rawApi = (container.dataset.api || "").replace(/\/$/, "");
  var _proxyPath = (container.dataset.proxy || "/apps/zipcheck").replace(/\/$/, "");
  // Prefer app.url when it looks like a full URL; otherwise use the relative proxy path
  // (which Shopify will forward to our app via the App Proxy config).
  var API_BASE = (_rawApi && _rawApi.indexOf("http") === 0) ? _rawApi : _proxyPath;

  // ── Pre-lock: applied synchronously BEFORE the async config fetch ────────────
  // This eliminates the race window where ATC/Buy Now buttons are clickable
  // while the config fetch is in flight (typically 100–500 ms).
  // renderWidget() will call _zccUnlock() immediately if the feature is
  // disabled (lockButtonsUntilZipCheck:false) or position is "inline".
  var _zccLockStyleId = 'zcc-lock-style';
  function _zccInjectLockCss() {
    if (document.getElementById(_zccLockStyleId)) return;
    var s = document.createElement('style');
    s.id = _zccLockStyleId;
    s.textContent =
      'html[data-zcc-locked] form[action*="/cart/add"] button[type="submit"],' +
      'html[data-zcc-locked] button[name="add"],' +
      'html[data-zcc-locked] .product-form__submit,' +
      'html[data-zcc-locked] [data-product-add],' +
      'html[data-zcc-locked] .btn--add-to-cart,' +
      'html[data-zcc-locked] .product-form button[type="submit"],' +
      'html[data-zcc-locked] button.product-form__cart-submit,' +
      'html[data-zcc-locked] .product__submit button[type="submit"],' +
      'html[data-zcc-locked] .pdp-form button[type="submit"]' +
      '{opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
      'html[data-zcc-locked] .shopify-payment-button,' +
      'html[data-zcc-locked] [data-shopify="payment-button"],' +
      'html[data-zcc-locked] .shopify-payment-button__button--unbranded' +
      '{position:relative!important;opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
      'html[data-zcc-locked] .shopify-payment-button::after,' +
      'html[data-zcc-locked] [data-shopify="payment-button"]::after' +
      '{content:""!important;position:absolute!important;inset:0!important;z-index:2147483647!important;cursor:not-allowed!important;background:transparent!important;}';
    (document.head || document.documentElement).appendChild(s);
  }
  function _zccLock() {
    _zccInjectLockCss();
    document.documentElement.setAttribute('data-zcc-locked', '1');
  }
  function _zccUnlock() {
    document.documentElement.removeAttribute('data-zcc-locked');
  }
  // Lock immediately — but skip if the customer already validated this shop's
  // ZIP in this session (avoids flash-of-disabled-buttons on page refresh).
  var _priorValid = false;
  try {
    _priorValid = sessionStorage.getItem('zcc:valid') === 'true' &&
                  sessionStorage.getItem('zcc:shop') === SHOP;
  } catch(e) {}
  if (!_priorValid) {
    _zccLock();
  }

  // Always fetch fresh config from the API so color/setting changes made in the
  // admin are reflected on the storefront immediately. The metafield-embedded
  // data-config attribute is intentionally ignored here: it is baked into
  // Shopify's CDN-cached HTML at render time and can be stale for many minutes
  // after a merchant saves new settings. The API endpoint returns
  // Cache-Control: no-store so it is always up to date.
  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
    .then(function (r) {
      if (!r.ok) throw new Error("Widget config API returned " + r.status);
      return r.json();
    })
    .then(function (cfg) { renderWidget(cfg); })
    .catch(function (err) {
      console.warn("[Pinzo] Could not load widget config, using defaults:", err.message || err);
      renderWidget({});
    });

  function renderWidget(cfg) {
    // Merge with defaults
    var D = {
      position: "inline",
      heading: "Check Delivery Availability",
      placeholder: "Enter your zip code",
      buttonText: "Check",
      successMessage: "Great news! We deliver to your area.",
      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
      notFoundMessage: "We currently do not ship to this ZIP code.",
      primaryColor: "#008060",
      successColor: "#008060",
      errorColor: "#D72C0D",
      backgroundColor: "#FFFFFF",
      textColor: "#202223",
      borderRadius: "8",
      showEta: true,
      showZone: false,
      showWaitlistOnFailure: false,
      showCod: true,
      showReturnPolicy: true,
      showCutoffTime: true,
      showDeliveryDays: true,
      showDeliveryDate: true,
      showCountdown: true,
      showDeliveryFee: true,
      customCss: "",
      blockCartOnInvalid: false,
      showSocialProof: true,
    };
    // Default lockButtonsUntilZipCheck to true
    if (cfg.lockButtonsUntilZipCheck === undefined || cfg.lockButtonsUntilZipCheck === null) {
      cfg.lockButtonsUntilZipCheck = true;
    }
    Object.keys(D).forEach(function (k) {
      if (cfg[k] === undefined || cfg[k] === null) cfg[k] = D[k];
    });

    // Release pre-lock if feature is disabled OR widget is inline
    // (inline widget is directly visible — customer doesn't need to hunt for it)
    if (!cfg.lockButtonsUntilZipCheck || cfg.position === 'inline') {
      _zccUnlock();
    }

    var rad = cfg.borderRadius + "px";
    var WID = "zcc-" + ROOT_ID;

    if (cfg.position === "floating") {
      renderFloating(cfg, WID, rad);
    } else if (cfg.position === "popup") {
      renderPopup(cfg, WID, rad);
    } else {
      renderInline(cfg, WID, rad);
    }

    // If blockCartOnInvalid is enabled, disable ATC/Buy Now buttons on page load
    // until the customer validates their ZIP code
    if (cfg.blockCartOnInvalid) {
      blockCartButtonsInitial();
    }

    // If lockButtonsUntilZipCheck is enabled AND the widget is in floating or popup mode,
    // disable ATC/Buy Now buttons until the customer successfully validates their ZIP code.
    // This is separate from blockCartOnInvalid (which also re-blocks on invalid).
    // lockButtonsUntilZipCheck only activates in non-inline modes (floating/popup) because
    // in those modes the widget is not directly visible on the product page by default.
    if (cfg.lockButtonsUntilZipCheck && (cfg.position === "floating" || cfg.position === "popup")) {
      lockAtcButtonsForZipCheck();
    }
  }

  // ── Block ATC buttons on page load (before any ZIP check) ─────────────────
  function blockCartButtonsInitial() {
    var ATC_SELECTORS = [
      'button[name="add"]',
      '.product-form__submit',
      '[data-product-add]',
      '.btn--add-to-cart',
      '.product-form button[type="submit"]',
      'button.shopify-payment-button__button',
      '.shopify-payment-button button',
      'button.product-form__cart-submit'
    ].join(',');

    function doBlock() {
      try {
        var atcBtns = document.querySelectorAll(ATC_SELECTORS);
        atcBtns.forEach(function(b) {
          if (!b.closest('[data-zcc-widget]')) {
            if (!b.getAttribute('data-zcc-blocked')) {
              b.setAttribute('data-zcc-orig-title', b.title || '');
            }
            b.disabled = true;
            b.style.opacity = '0.5';
            b.title = 'Please check ZIP code availability first';
            b.setAttribute('data-zcc-blocked', 'true');
          }
        });
      } catch(e) {}
    }

    // Block immediately + delays for dynamic buttons (Shopify Buy Now renders late)
    doBlock();
    setTimeout(doBlock, 500);
    setTimeout(doBlock, 1500);

    // MutationObserver for dynamic payment buttons
    if (typeof MutationObserver !== 'undefined') {
      var observer = new MutationObserver(function() { doBlock(); });
      var form = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]');
      if (form) {
        observer.observe(form, { childList: true, subtree: true });
        setTimeout(function() { observer.disconnect(); }, 10000);
      }
    }
  }

  // ── Wire up lock/unlock listeners (floating/popup mode) ─────────────────────
  // Pre-lock is already applied synchronously above via _zccLock().
  // This function wires up zcc:validated so buttons unlock on success.
  function lockAtcButtonsForZipCheck() {
    // Start in the correct state — if the customer already validated, treat as verified.
    var zipVerified = _priorValid;

    window.addEventListener('zcc:validated', function(e) {
      var detail = e.detail;
      if (detail && detail.valid === true) {
        zipVerified = true;
        _zccUnlock();
      } else if (detail && detail.valid === false) {
        zipVerified = false;
        _zccLock();
      }
    });

    // Re-lock if customer edits ZIP field after a successful check
    document.addEventListener('input', function(e) {
      var t = e.target;
      if (t && t.classList && t.classList.contains('zcc-input') && zipVerified) {
        zipVerified = false;
        _zccLock();
      }
    });
  }

  // ── Scope custom CSS: auto-prefix selectors with widget container ID ──────
  function scopeCustomCss(rawCss, wid) {
    if (!rawCss) return "";
    // Strip </style> tags to prevent injection
    var css = rawCss.replace(/<\/style>/gi, "");
    var result = "";
    var i = 0;
    while (i < css.length) {
      // Skip whitespace
      while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
      if (i >= css.length) break;
      // Pass through @keyframes and @font-face unchanged
      if (css[i] === '@') {
        var atRule = "";
        var j = i;
        while (j < css.length && css[j] !== '{' && css[j] !== ';') { atRule += css[j]; j++; }
        var atName = atRule.trim().toLowerCase();
        if (atName.indexOf("@keyframes") === 0 || atName.indexOf("@font-face") === 0) {
          result += atRule;
          if (j < css.length && css[j] === '{') {
            var depth = 1; result += css[j]; j++;
            while (j < css.length && depth > 0) {
              if (css[j] === '{') depth++;
              if (css[j] === '}') depth--;
              result += css[j]; j++;
            }
          }
          i = j; continue;
        }
        // @media: scope inner rules
        if (atName.indexOf("@media") === 0) {
          result += atRule;
          if (j < css.length && css[j] === '{') {
            result += '{'; j++;
            // Collect inner content
            var depth = 1; var inner = "";
            while (j < css.length && depth > 0) {
              if (css[j] === '{') depth++;
              if (css[j] === '}') depth--;
              if (depth > 0) inner += css[j];
              j++;
            }
            result += scopeCustomCss(inner, wid);
            result += '}';
          }
          i = j; continue;
        }
      }
      // Regular rule: grab selector, prefix with #wid
      var sel = ""; var body = "";
      while (i < css.length && css[i] !== '{') { sel += css[i]; i++; }
      if (i < css.length) { i++; } // skip {
      var depth = 1;
      while (i < css.length && depth > 0) {
        if (css[i] === '{') depth++;
        if (css[i] === '}') depth--;
        if (depth > 0) body += css[i];
        i++;
      }
      if (sel.trim()) {
        // Split multiple selectors by comma and prefix each
        var selectors = sel.split(',').map(function(s) {
          s = s.trim();
          if (!s) return '';
          return '#' + wid + ' ' + s;
        }).filter(Boolean).join(', ');
        result += selectors + ' {' + body + '}';
      }
    }
    return result;
  }

  // ── Delivery date formatter ───────────────────────────────────────────────────
  function formatDeliveryDate(isoDate) {
    if (!isoDate) return null;
    try {
      var parts = isoDate.split('-');
      var d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
      var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
      var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
      return days[d.getDay()] + ', ' + months[d.getMonth()] + ' ' + d.getDate();
    } catch(e) { return null; }
  }

  // ── Countdown timer functions ─────────────────────────────────────────────────
  function getCountdownData(cutoffTime) {
    if (!cutoffTime) return null;
    var parts = cutoffTime.split(':');
    var cutoffHr = parseInt(parts[0], 10);
    var cutoffMin = parseInt(parts[1] || '0', 10);
    var now = new Date();
    var cutoff = new Date();
    cutoff.setHours(cutoffHr, cutoffMin, 0, 0);
    var diff = cutoff - now;
    if (diff <= 0) return { passed: true, hours: 0, minutes: 0 };
    var hours = Math.floor(diff / 3600000);
    var minutes = Math.floor((diff % 3600000) / 60000);
    return { passed: false, hours: hours, minutes: minutes };
  }

  function buildCountdownHtml(cutoffTime, widgetId) {
    var cd = getCountdownData(cutoffTime);
    if (!cd) return '';
    var colorClass, text;
    if (cd.passed) {
      colorClass = 'zcc-countdown--passed';
      text = 'Order now for next business day dispatch';
    } else {
      var totalMinutes = cd.hours * 60 + cd.minutes;
      if (totalMinutes > 180) colorClass = 'zcc-countdown--green';
      else if (totalMinutes > 60) colorClass = 'zcc-countdown--amber';
      else colorClass = 'zcc-countdown--red';
      text = 'Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch';
    }
    return '<div class="zcc-countdown ' + colorClass + '" id="' + widgetId + '-countdown">' + ICONS.clock + '<span>' + text + '</span></div>';
  }

  function startCountdownUpdater(widgetId, cutoffTime) {
    if (!cutoffTime) return;
    setInterval(function() {
      var el = document.getElementById(widgetId + '-countdown');
      if (!el) return;
      var cd = getCountdownData(cutoffTime);
      if (!cd) return;
      if (cd.passed) {
        el.className = 'zcc-countdown zcc-countdown--passed';
        el.innerHTML = ICONS.clock + '<span>Order now for next business day dispatch</span>';
        return;
      }
      var totalMinutes = cd.hours * 60 + cd.minutes;
      var cls = totalMinutes > 180 ? 'zcc-countdown--green' : totalMinutes > 60 ? 'zcc-countdown--amber' : 'zcc-countdown--red';
      el.className = 'zcc-countdown ' + cls;
      el.innerHTML = ICONS.clock + '<span>Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch</span>';
    }, 30000);
  }

  // ── Shared meta/waitlist CSS — injected by all three style presets ──────────
  function buildSharedCss(W, cfg) {
    return (
      // Spin animation for loading spinner
      "@keyframes zcc-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}" +
      // CSS-only ring spinner — rendered as the sole button child during loading
      W + " .zcc-spinner{display:block !important;width:18px !important;height:18px !important;border-radius:50% !important;" +
        "border:2.5px solid rgba(255,255,255,0.35) !important;border-top-color:#fff !important;" +
        "animation:zcc-spin 0.7s linear infinite !important;flex-shrink:0 !important}" +
      // Button icon/label structure
      W + " .zcc-btn-icon{display:inline-flex !important;align-items:center !important;flex-shrink:0 !important}" +
      W + " .zcc-btn-icon svg{width:15px !important;height:15px !important;display:block !important}" +
      W + " .zcc-btn-label{display:inline !important}" +
      // Loading state: button already has display:flex + justify-content:center from .zcc-btn,
      // so the lone .zcc-spinner child is automatically centred — just remove the gap
      W + " .zcc-btn--loading{gap:0 !important}" +
      // Result card layout
      // Icon container is 32px so the 4px background-circle padding still gives a 24px
      // content area for the SVG under box-sizing:border-box — previously 24px with 4px
      // padding compressed the SVG to 16px which looked inconsistent between ok/fail.
      W + " .zcc-result-icon{flex-shrink:0 !important;width:32px !important;height:32px !important;display:flex !important;align-items:center !important;justify-content:center !important;box-sizing:content-box !important}" +
      W + " .zcc-result-icon svg{width:20px !important;height:20px !important;display:block !important}" +
      W + " .zcc-result-content{flex:1 !important;min-width:0 !important}" +
      W + " .zcc-result-message{font-size:13.5px !important;font-weight:600 !important;line-height:1.4 !important}" +
      W + " .zcc-result.ok .zcc-result-icon{background:" + cfg.successColor + "15 !important;border-radius:50% !important;padding:6px !important}" +
      W + " .zcc-result.ok .zcc-result-message{color:" + cfg.successColor + " !important}" +
      W + " .zcc-result.fail .zcc-result-icon{background:" + cfg.errorColor + "15 !important;border-radius:50% !important;padding:6px !important}" +
      W + " .zcc-result.fail .zcc-result-message{color:" + cfg.errorColor + " !important}" +
      // Meta info rows (ETA, zone, days, cutoff)
      W + " .zcc-meta{margin-top:6px !important;font-size:13px !important;display:flex !important;align-items:center !important;gap:7px !important;color:#4b5563 !important;line-height:1.4 !important}" +
      W + " .zcc-meta svg{width:14px !important;height:14px !important;flex-shrink:0 !important;opacity:0.7 !important}" +
      W + " .zcc-meta strong{font-weight:600 !important;color:" + cfg.textColor + " !important}" +
      W + " .zcc-meta span{flex:1 !important}" +
      W + " .zcc-cutoff{margin-top:5px !important;font-size:12px !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:7px !important}" +
      W + " .zcc-cutoff svg{width:13px !important;height:13px !important;flex-shrink:0 !important;opacity:0.6 !important}" +
      W + " .zcc-days{margin-top:5px !important;font-size:12px !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:7px !important}" +
      W + " .zcc-days svg{width:13px !important;height:13px !important;flex-shrink:0 !important;opacity:0.6 !important}" +
      // COD badge
      W + " .zcc-cod{margin-top:8px !important;display:inline-flex !important;align-items:center !important;gap:5px !important;border-radius:20px !important;padding:4px 10px !important;font-size:12px !important;font-weight:600 !important}" +
      W + " .zcc-cod svg{width:13px !important;height:13px !important;flex-shrink:0 !important}" +
      W + " .zcc-cod--available{background:" + cfg.successColor + "12 !important;border:1px solid " + cfg.successColor + "25 !important;color:" + cfg.successColor + " !important}" +
      W + " .zcc-cod--unavailable{background:#d72c0d10 !important;border:1px solid #d72c0d22 !important;color:#d72c0d !important}" +
      // Return policy row
      W + " .zcc-return-policy{margin-top:5px !important;font-size:12px !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:7px !important}" +
      W + " .zcc-return-policy svg{width:13px !important;height:13px !important;flex-shrink:0 !important;opacity:0.6 !important}" +
      W + " .zcc-return-policy span{flex:1 !important}" +
      // Delivery date
      W + " .zcc-delivery-date{margin-top:5px !important;font-size:12px !important;color:#4b5563 !important;display:flex !important;align-items:center !important;gap:7px !important;line-height:1.4 !important}" +
      W + " .zcc-delivery-date svg{width:14px !important;height:14px !important;flex-shrink:0 !important;opacity:0.7 !important}" +
      W + " .zcc-delivery-date strong{font-weight:600 !important;color:" + cfg.textColor + " !important}" +
      // Countdown
      W + " .zcc-countdown{margin-top:5px !important;font-size:12px !important;display:flex !important;align-items:center !important;gap:7px !important;line-height:1.4 !important}" +
      W + " .zcc-countdown svg{width:13px !important;height:13px !important;flex-shrink:0 !important;opacity:0.7 !important}" +
      W + " .zcc-countdown strong{font-weight:700 !important}" +
      W + " .zcc-countdown--green{color:#16a34a !important}" +
      W + " .zcc-countdown--green strong{color:#16a34a !important}" +
      W + " .zcc-countdown--amber{color:#d97706 !important}" +
      W + " .zcc-countdown--amber strong{color:#d97706 !important}" +
      W + " .zcc-countdown--red{color:#dc2626 !important}" +
      W + " .zcc-countdown--red strong{color:#dc2626 !important}" +
      W + " .zcc-countdown--passed{color:#6d7175 !important}" +
      // Delivery fee
      W + " .zcc-delivery-fee{margin-top:8px !important;display:inline-flex !important;align-items:center !important;gap:5px !important;border-radius:20px !important;padding:4px 10px !important;font-size:12px !important;font-weight:600 !important}" +
      W + " .zcc-delivery-fee svg{width:13px !important;height:13px !important;flex-shrink:0 !important}" +
      W + " .zcc-delivery-fee--free{background:" + cfg.successColor + "12 !important;border:1px solid " + cfg.successColor + "25 !important;color:" + cfg.successColor + " !important}" +
      W + " .zcc-delivery-fee--paid{background:#f59e0b10 !important;border:1px solid #f59e0b22 !important;color:#92400e !important}" +
      // Waitlist toggle
      W + " .zcc-wl-toggle{display:flex !important;align-items:center !important;gap:12px !important;font-size:13.5px !important;font-weight:600 !important;color:" + cfg.primaryColor + " !important;text-decoration:none !important;cursor:pointer !important;border:none !important;background:none !important;padding:0 !important;width:100% !important;text-align:left !important}" +
      W + " .zcc-wl-toggle:hover{text-decoration:underline !important}" +
      W + " .zcc-wl-toggle svg{width:20px !important;height:20px !important;flex-shrink:0 !important;background:" + cfg.primaryColor + "15 !important;border-radius:50% !important;padding:6px !important;display:block !important;box-sizing:content-box !important}" +
      // Waitlist form inputs
      W + " .zcc-wl-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "20 !important}" +
      // Waitlist submit button icon sizing and disabled state
      // Base styles, hover, active are defined in buildWidgetCss so they
      // pick up btnRadius and primaryColor shadow — matching the Check button.
      W + " .zcc-wl-btn-icon{display:inline-flex !important;align-items:center !important;flex-shrink:0 !important}" +
