 47→export const loader = async ({ request }: LoaderFunctionArgs) => {
 48→  const { session } = await authenticate.admin(request);
 49→  const shop = session.shop;
 50→
 51→  const [rules, zones, subscription] = await Promise.all([
 52→    db.deliveryRule.findMany({
 53→      where: { shop },
 54→      orderBy: { priority: "asc" },
 55→    }),
 56→    db.zipCode.findMany({
 57→      where: { shop, zone: { not: null } },
 58→      select: { zone: true },
 59→      distinct: ["zone"],
 60→    }),
 61→    getShopSubscription(shop),
 62→  ]);
 63→
 64→  return {
 65→    rules,
 66→    zones: zones.map((z) => z.zone).filter(Boolean) as string[],
 67→    subscription,
 68→  };
 69→};
 70→
 71→export const action = async ({ request }: ActionFunctionArgs) => {
 72→  const { session } = await authenticate.admin(request);
 73→  const shop = session.shop;
 74→  const formData = await request.formData();
 75→  const intent = formData.get("intent");
 76→
 77→  if (intent === "create" || intent === "update") {
 78→    const id = String(formData.get("id") || "");
 79→    const name = String(formData.get("name") || "").trim();
 80→    const zone = String(formData.get("zone") || "").trim() || null;
 81→    const zipCodes = String(formData.get("zipCodes") || "").trim() || null;
 82→    const minOrderAmount = formData.get("minOrderAmount")
 83→      ? parseFloat(String(formData.get("minOrderAmount")))
 84→      : null;
 85→    const deliveryFee = formData.get("deliveryFee")
 86→      ? parseFloat(String(formData.get("deliveryFee")))
 87→      : null;
 88→    const freeShippingAbove = formData.get("freeShippingAbove")
 89→      ? parseFloat(String(formData.get("freeShippingAbove")))
 90→      : null;
 91→    const estimatedDays =
 92→      String(formData.get("estimatedDays") || "").trim() || null;
 93→    const cutoffTime =
 94→      String(formData.get("cutoffTime") || "").trim() || null;
 95→    const daysOfWeek =
 96→      String(formData.get("daysOfWeek") || "").trim() || null;
 97→    const priority = parseInt(String(formData.get("priority") || "0"), 10);
 98→
 99→    if (!name) return { error: "Rule name is required." };
100→
101→    const data = {
102→      name,
103→      zone,
104→      zipCodes,
105→      minOrderAmount,
106→      deliveryFee,
107→      freeShippingAbove,
108→      estimatedDays,
109→      cutoffTime,
110→      daysOfWeek,
111→      priority,
112→    };
113→
114→    if (intent === "update" && id) {
115→      try {
116→        const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
117→        if (!existing) return { error: "Rule not found." };
118→        await db.deliveryRule.update({ where: { id }, data });
119→        return { success: true, action: "updated" };
120→      } catch {
121→        return { error: "Failed to update rule." };
122→      }
123→    } else {
124→      // Plan-gating: check limits before creating a new rule
125→      const subscription = await getShopSubscription(shop);
126→      const { maxDeliveryRules, label: planLabel } = subscription.limits;
127→
128→      if (maxDeliveryRules === 0) {
129→        return {
130→          error:
131→            "Delivery rules are not available on the Free plan. Upgrade to Starter or Pro.",
132→        };
133→      }
134→
135→      if (maxDeliveryRules < UNLIMITED) {
136→        const currentCount = await db.deliveryRule.count({ where: { shop } });
137→        if (currentCount >= maxDeliveryRules) {
138→          return {
139→            error: `You've reached the ${maxDeliveryRules} delivery rule limit on the ${planLabel} plan. Upgrade to Pro for unlimited rules.`,
140→          };
141→        }
142→      }
143→
144→      await db.deliveryRule.create({ data: { shop, ...data } });
145→      return { success: true, action: "created" };
146→    }
147→  }
148→
149→  if (intent === "delete") {
150→    const id = String(formData.get("id"));
151→    try {
152→      const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
153→      if (!existing) return { error: "Rule not found." };
154→      await db.deliveryRule.delete({ where: { id } });
155→      return { success: true, action: "deleted" };
156→    } catch {
157→      return { error: "Failed to delete rule." };
158→    }
159→  }
160→
161→  if (intent === "toggle") {
162→    const id = String(formData.get("id"));
163→    const isActive = formData.get("isActive") === "true";
164→    try {
165→      const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
166→      if (!existing) return { error: "Rule not found." };
167→      await db.deliveryRule.update({
168→        where: { id },
169→        data: { isActive: !isActive },
170→      });
171→      return { success: true, action: "toggled" };
172→    } catch {
173→      return { error: "Failed to toggle rule." };
174→    }
175→  }
176→
177→  return null;
178→};
