import { useState, useCallback, useMemo, useEffect, useRef } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";
import { getShopSubscription } from "../billing.server";
import { PLAN_LIMITS, UNLIMITED } from "../plans";
import {
  Page,
  Layout,
  Card,
  TextField,
  Button,
  Banner,
  BlockStack,
  InlineStack,
  InlineGrid,
  Text,
  Badge,
  IndexTable,
  type IndexTableProps,
  Modal,
  Select,
  Divider,
  EmptyState,
  Box,
  Icon,
  Tooltip,
  DropZone,
} from "@shopify/polaris";
import {
  SearchIcon,
  DeleteIcon,
  EditIcon,
  PlusIcon,
  StarIcon,
  ImportIcon,
  ExportIcon,
} from "@shopify/polaris-icons";

const PAGE_SIZE = 10;

/** RFC-4180 compliant CSV row parser — handles quoted fields containing commas. */
function parseCsvRow(line: string): string[] {
  const cols: string[] = [];
  let cur = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') {
        cur += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (ch === "," && !inQuotes) {
      cols.push(cur.trim());
      cur = "";
    } else {
      cur += ch;
    }
  }
  cols.push(cur.trim());
  return cols;
}

/** Downloads a pre-filled sample CSV template the user can fill in and import. */
function downloadSampleCsv() {
  const sample = [
