            {/* Total */}
            <Card padding="400">
              <BlockStack gap="150">
                <Text as="p" tone="subdued" variant="bodySm">
                  Total Zip Codes
                </Text>
                <InlineStack gap="150" blockAlign="center">
                  <Text as="p" variant="headingXl" fontWeight="bold">
                    {stats.total}
                  </Text>
                  {limits.maxZipCodes < UNLIMITED && (
                    <Text as="p" tone="subdued" variant="bodySm">
