                >
                  <TextField
                    label="Zip code"
                    value={checkZip}
                    onChange={setCheckZip}
                    placeholder="e.g. 90210"
                    autoComplete="off"
                    labelHidden
                    prefix={<Icon source={SearchIcon} />}
                    connectedRight={
                      <Button
                        onClick={handleCheck}
