        open={addModalOpen}
        onClose={() => {
          setAddModalOpen(false);
          setNewZip("");
          setNewLabel("");
          setNewZone("");
          setNewMessage("");
          setNewEta("");
          setNewType("allowed");
          setNewCodAvailable("");
          setNewReturnPolicy("");
        }}
        title="Add Zip Code"
        primaryAction={{
          content: "Add Zip Code",
          onAction: handleAdd,
          loading: isAddLoading,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setAddModalOpen(false);
              setNewZip("");
              setNewLabel("");
              setNewZone("");
              setNewMessage("");
              setNewEta("");
              setNewType("allowed");
              setNewCodAvailable("");
              setNewReturnPolicy("");
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {actionError && (
              <Banner
                tone="critical"
                action={
                  upgradeRequired
                    ? {
                        content: "View Pricing Plans",
                        onAction: () => {
                          setAddModalOpen(false);
                          navigate("/app/pricing");
                        },
                      }
                    : undefined
                }
              >
                {actionError}
              </Banner>
            )}
            <TextField
              label="Zip Code"
              value={newZip}
              onChange={setNewZip}
              placeholder="e.g. 90210"
              autoComplete="off"
              helpText="Enter a 5-digit US zip code or postal code."
            />
            <InlineStack gap="300">
              <Box minWidth="0" width="100%">
                <TextField
                  label="Zone"
                  value={newZone}
                  onChange={setNewZone}
                  placeholder="e.g. Manhattan, Beverly Hills"
                  autoComplete="off"
                  helpText="The delivery zone or area name."
                />
              </Box>
              <Box minWidth="0" width="100%">
                <Select
                  label="Status"
                  options={typeOptions}
                  value={newType}
                  onChange={setNewType}
                  helpText={
                    !limits.allowBlocked
                      ? "Blocked zip codes require Pro or Ultimate plan."
                      : "Allow or block this zip code."
                  }
                />
              </Box>
            </InlineStack>
            <TextField
              label="Message"
              value={newMessage}
              onChange={setNewMessage}
              placeholder="e.g. Delivery available!, Sorry we don't deliver here"
              autoComplete="off"
              helpText="Custom message shown to customers for this zip code."
            />
            <InlineStack gap="300">
              <Box minWidth="0" width="100%">
                <TextField
                  label="ETA"
                  value={newEta}
                  onChange={setNewEta}
                  placeholder="e.g. 2-3 days"
                  autoComplete="off"
                  helpText="Estimated delivery time."
                />
              </Box>
              <Box minWidth="0" width="100%">
                <TextField
                  label="Label (optional)"
                  value={newLabel}
                  onChange={setNewLabel}
                  placeholder="e.g. Downtown LA"
                  autoComplete="off"
                  helpText="Internal label for your reference."
                />
