          "><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>Check</button>
        </div>
        <div style="
          margin-top:16px;padding:14px 16px;border-radius:8px;
          background:linear-gradient(135deg,#00806008,#00806014);border:1px solid #00806030;
          font-size:14px;color:#008060;line-height:1.5;
