                </InlineStack>

                {/* Row 2: Description + Read more */}
                <BlockStack gap="100">
                  <Text as="p" tone="subdued" variant="bodyMd">
                    {displayDescription}
                  </Text>
                  {needsTruncation && (
                    <Button
                      variant="plain"
                      size="slim"
                      onClick={() =>
                        handleToggleExpand(feature.id)
